pub fn soma_dos_dias(dias: i32) -> i32 {
    let mut total = 0;
    for dia in 1..=dias {
        total += dia;
    }
    total
}

pub fn treinos_ate_a_meta(meta: i32, por_treino: i32) -> i32 {
    let mut acumulado = 0;
    let mut treinos = 0;
    while acumulado < meta {
        acumulado += por_treino;
        treinos += 1;
    }
    treinos
}

pub fn dobras_ate_passar(distancia: i32) -> i32 {
    let mut atual = distancia;
    let mut dobras = 0;
    loop {
        atual = atual * 2;
        dobras += 1;
        if atual > 100 {
            break dobras;
        }
    }
}

